    dist_o = bfs((ox, oy))
    INF = 10**9
    candidates = []
    for rx, ry in resources:
        ds = dist_s[rx][ry]
        do = dist_o[rx][ry]
        if ds >= INF or do >= INF:
            continue
        key = (do - ds, -ds, rx, ry)
        candidates.append((key, (rx, ry)))
    if not candidates:
        return [0, 0]
    candidates.sort(key=lambda t: t[0], reverse=True)
    tx, ty = candidates[0][1]

